package app.manga.library;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="user_library",uniqueConstraints=@UniqueConstraint(name="uq_user_manga",columnNames={"user_id","provider","external_manga_id"}))public class LibraryEntry{@Id private UUID id;@Column(name="user_id",nullable=false)private UUID userId;@Column(nullable=false,length=30)private String provider;@Column(name="external_manga_id",nullable=false)private long externalMangaId;@Column(name="title_snapshot",nullable=false,length=500)private String titleSnapshot;@Column(name="cover_url_snapshot")private String coverUrlSnapshot;@Column(name="reading_status",nullable=false,length=30)private String readingStatus;@Column(name="added_at",nullable=false)private Instant addedAt;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false)private Instant updatedAt=Instant.now();protected LibraryEntry(){}public LibraryEntry(UUID user,String provider,long manga,String title,String cover,String status,Instant added,Instant updated){id=UUID.randomUUID();userId=user;this.provider=provider;externalMangaId=manga;titleSnapshot=title;coverUrlSnapshot=cover;readingStatus=status;addedAt=added==null?Instant.now():added;updatedAt=updated==null?Instant.now():updated;}public UUID getId(){return id;}public UUID getUserId(){return userId;}public String getProvider(){return provider;}public long getExternalMangaId(){return externalMangaId;}public String getTitleSnapshot(){return titleSnapshot;}public String getCoverUrlSnapshot(){return coverUrlSnapshot;}public String getReadingStatus(){return readingStatus;}public Instant getAddedAt(){return addedAt;}public Instant getUpdatedAt(){return updatedAt;}public void changeStatus(String s){readingStatus=s;updatedAt=Instant.now();}public void merge(LibraryEntry other){if(other.updatedAt!=null&&other.updatedAt.isAfter(updatedAt)){readingStatus=other.readingStatus;updatedAt=other.updatedAt;}}}
